#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
mkdir -p storage
cargo build --release --offline
exec cargo run --release --offline --quiet --bin quizzy

