const APP_CSS: &str = include_str!("../assets/app.css");
const FONT: &[u8] = include_bytes!("../docs/mockups/Inter-latin.woff2");

#[derive(Clone)]
struct AppState {
    db_path: PathBuf,
    username: String,
    password: String,
    csrf_token: String,
}

#[derive(Debug, Clone)]
struct QuizSummary {
    id: i64,
    title: String,
    total: i64,
    active: i64,
}

#[derive(Debug, Clone)]
struct Quiz {
    id: i64,
    title: String,
    number_of_winners: i64,
    questions: Vec<Question>,
}

#[derive(Debug, Clone)]
struct Question {
    id: i64,
    body: String,
    active: bool,
    options: Vec<OptionItem>,
}

#[derive(Debug, Clone)]
struct OptionItem {
    body: String,
    correct: bool,
}

#[derive(Serialize)]
struct PreviewQuestion {
    body: String,
    options: Vec<PreviewOption>,
}

#[derive(Serialize)]
struct PreviewOption {
    body: String,
    correct: bool,
}

// This is the complete, stable interchange format: do not add database or
// application fields here. Both import and export use this exact shape.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct QuizTransfer {
    title: String,
    questions: Vec<TransferQuestion>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct TransferQuestion {
    text: String,
    #[serde(default = "default_active")]
    active: bool,
    options: Vec<TransferOption>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct TransferOption {
    text: String,
    #[serde(default)]
    correct: bool,
}

#[derive(Debug)]
struct ValidatedQuiz(QuizTransfer);

#[derive(Deserialize)]
struct QuizForm {
    #[serde(default)]
    csrf: String,
    #[serde(default)]
    title: String,
    #[serde(default = "default_number_of_winners")]
    number_of_winners: i64,
}

#[derive(Deserialize)]
struct ImportQuizForm {
    #[serde(default)]
    csrf: String,
    #[serde(default)]
    quiz_json: String,
}

#[derive(Deserialize)]
struct CsrfForm {
    #[serde(default)]
    csrf: String,
}

#[derive(Deserialize)]
struct QuestionForm {
    #[serde(default)]
    csrf: String,
    #[serde(default)]
    question: String,
    #[serde(default)]
    option_text: Vec<String>,
    #[serde(default)]
    correct_index: Vec<usize>,
    #[serde(default)]
    active: Option<bool>,
}

#[derive(Deserialize)]
struct ActiveForm {
    #[serde(default)]
    csrf: String,
    #[serde(default)]
    active: Option<bool>,
}

#[derive(Deserialize)]
struct MoveForm {
    #[serde(default)]
    csrf: String,
    direction: String,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let username = required_env("QUIZZY_MODERATOR_USERNAME")?;
    let password = required_env("QUIZZY_MODERATOR_PASSWORD")?;
    let secret = required_env("SECRET_KEY_BASE")?;
    let port = env::var("PORT")
        .unwrap_or_else(|_| "3000".to_owned())
        .parse::<u16>()?;

    let storage = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("storage");
    fs::create_dir_all(&storage)?;
    let db_path = storage.join("quizzy.sqlite3");
    initialize_database(&db_path)?;

    // The key is never sent to the browser. Only this keyed, fixed-purpose form token is.
    let mut digest = Sha256::new();
    digest.update(secret.as_bytes());
    digest.update(b"\0quizzy moderator form token v1");
    let csrf_token = format!("{:x}", digest.finalize());

    let state = AppState {
        db_path,
        db_path,
        username,
        password,
        csrf_token,
    };

    // The outer middleware also protects unknown /moderate paths, not only registered pages.
    let app = Router::new()
        .route("/up", get(up))
        .route("/assets/quizzy.css", get(quizzy_css))
        .route("/assets/app.css", get(app_css))
        .route("/assets/Inter-latin.woff2", get(font))
        .route("/moderate", get(list_quizzes))
        .route("/moderate/", get(list_quizzes))
        .route(
            "/moderate/quizzes/import",
            get(import_quiz_page).post(import_quiz),
        )
        .route("/moderate/quizzes/new", get(new_quiz))
        .route("/moderate/quizzes", post(create_quiz))
        .route("/moderate/quizzes/{quiz_id}/export", get(export_quiz))
      ",
  "output_tail": "INTO options(question_id, body, is_correct, position)
                 VALUES (?1, ?2, ?3, ?4)",
                params![
                    question_id,
                    option.text,
                    option.correct,
                    option_position as i64
                ],
            )?;
        }
    }

    transaction.commit()?;
    Ok(quiz_id)
}

fn default_active() -> bool {
    true
}

async fn show_quiz(State(state): State<AppState>, Path(quiz_id): Path<i64>) -> Response {
    match load_quiz(&state.db_path, quiz_id) {
        Ok(Some(quiz)) => Html(render_quiz_page(&state, &quiz)).into_response(),
        Ok(None) => not_found(),
        Err(error) => internal_error(error),
    }
}

fn transfer_from_quiz(quiz: &Quiz) -> QuizTransfer {
    QuizTransfer {
        title: quiz.title.clone(),
        questions: quiz
            .questions
            .iter()
            .map(|question| TransferQuestion {
                text: question.body.clone(),
                active: question.active,
                options: question
                    .options
                    .iter()
                    .map(|option| TransferOption {
                        text: option.body.clone(),
                        correct: option.correct,
                    })
                    .collect(),
            })
            .collect(),
    }
}

async fn export_quiz(State(state): State<AppState>, Path(quiz_id): Path<i64>) -> Response {
    match load_quiz(&state.db_path, quiz_id) {
        Ok(Some(quiz)) => {
            let transfer = transfer_from_quiz(&quiz);
            match serde_json::to_string_pretty(&transfer) {
                Ok(json) => {
                    let content = format!(
                        "<div class=\"breadcrumbs\"><a href=\"/moderate/quizzes/{}\">← {}</a></div><div class=\"page-head\"><div><h1>Export quiz</h1><p class=\"meta\">Copy this JSON to move the quiz to another Quizzy app.</p></div></div><pre class=\"quiz-json\">{}</pre>",
                        quiz.id,
                        escape_html(&quiz.title),
                        escape_html(&json)
                    );
                    Html(page("Export quiz", &content)).into_response()
                }
                Err(error) => internal_error(error),
            }
        }
        Ok(None) => not_found(),
        Err(error) => internal_error(error),
    }
}

async fn edit_quiz(State(state): State<AppState>, Path(quiz_id): Path<i64>) -> Response {
    match load_quiz(&state.db_path, quiz_id) {
        Ok(Some(quiz)) => Html(render_quiz_form(
            &state,
            Some(quiz.id),
            &quiz.title,
            quiz.number_of_winners,
            &[],
        ))
        .into_response(),
        Ok(None) => not_found(),
        Err(error) => internal_error(error),
    }
}

async fn update_quiz(
    State(state): State<AppState>,
    Path(quiz_id): Path<i64>,
    Form(form): Form<QuizForm>,
) -> Response {
    if !csrf_valid(&state, &form.csrf) {
        return csrf_error();
    }
    let Ok(Some(_)) = load_quiz(&state.db_path, quiz_id) else {
        return not_found();
    };
    let title = form.title.trim();
    if title.is_empty() {
        return Html(render_quiz_form(
            &state,
            Some(quiz_id),
            &form.title,
            form.number_of_winners,
            &["Title is required".to_owned()],
        ))
        .into_response();
    }
    if form.number_of_winners < 1 {
        return Html(render_quiz_form(
            &state,
            Some(quiz_id),
            &form.title,
            form.number_of_winners,
            &["Number of winners must be at least 1".to_owned()],
        ))
        .into_response();
    }
    match open_database(&state.db_path).and_then(|connection| {
        connection.execute(
            "UPDATE quizzes SET title = ?1, number_of_winners = ?2 WHERE id = ?3",
            params![title, form.number_of_winners, quiz_id],
        )
    }) {
        Ok(_) => Redirect::to(&format!("/moderate/quizzes/{quiz_id}")).into_response(),
        Err(error) => internal_error(error),
    }
}

async fn delete_quiz(
    State(state): State<AppState>,
    Path(quiz_id): Path<i64>,
    Form(form): Form<CsrfForm>,
) -> Response {
    if !csrf_valid(&state, &form.csrf) {
        return csrf_error();
    }
    match open_database(&state.db_path)
        .and_then(|connection| connection.execute("DELETE FROM quizzes WHERE id = ?1", [quiz_id]))
    {
        Ok(0) => not_found(),
        Ok(_) => Redirect::to("/moderate").into_response(),
        Err(error) => internal_error(error),
    }
}

async fn new_question(State(state): State<AppState>, Path(quiz_id): Path<i64>) -> Response {
    match load_quiz(&state.db_path, quiz_id) {
        Ok(Some(quiz)) => {
            Html(render_question_form(&state, &quiz, None, None, &[])).into_response()
        }
        Ok(None) => not_found(),
        Err(error) => internal_error(error),
    }
}

