   400	fn moderator_state(
   401	    path: &FsPath,
   402	    game_id: i64,
   403	    headers: &HeaderMap,
   404	) -> rusqlite::Result<Option<ModeratorGameState>> {
   405	    let connection = open_database(path)?;
