   410	    let players: i64 = connection.query_row(
   411	        "SELECT COUNT(*) FROM players WHERE game_id = ?1",
   412	        [game.id],
   413	        |row| row.get(0),
   414	    )?;
   415	    let question_count: i64 = connection.query_row(
   416	        "SELECT COUNT(*) FROM game_questions WHERE game_id = ?1",
   417	        [game.id],
   418	        |row| row.get(0),
   419	    )?;
   420	    let leaderboard = if game.status == "over" {
   421	        leaderboard_entries(&connection, game.id)?
   422	    } else {
   423	        Vec::new()
   424	    };
   425	    let mut state = ModeratorGameState {
   426	        status: game.status.clone(),
   427	        title: game.title,
   428	        code: game.code,
   429	        join_url,
   430	        players,
   431	        number_of_winners: game.number_of_winners,
   432	        current_position: None,
   433	        question_number: None,
   434	        question_count,
   435	        question_text: None,
   436	        answered: 0,
   437	        options: Vec::new(),
   438	        leaderboard,
   439	    };
   440	    if game.current_position < 0 {
   441	        return Ok(Some(state));
   442	    }
   443	
   444	    state.current_position = Some(game.current_position);
   445	    state.question_number = Some(game.current_position + 1);
   446	    let question: Option<(i64, String)> = connection
   447	        .query_row(
   448	            "SELECT id, body FROM game_questions WHERE game_id = ?1 AND position = ?2",
   449	            params![game.id, game.current_position],
   450	            |row| Ok((row.get(0)?, row.get(1)?)),
   451	        )
   452	        .optional()?;
   453	    let Some((question_id, body)) = question else {
   454	        return Ok(Some(state));
   455	    };
   456	    state.question_text = Some(body);
   457	
   458	    if game.status == "open" {
   459	        state.answered = connection.query_row(
   460	            "SELECT COUNT(*) FROM answers WHERE game_question_id = ?1",
   461	            [question_id],
   462	            |row| row.get(0),
   463	        )?;
   464	        let mut statement = connection.prepare(
   465	            "SELECT id, body FROM game_options WHERE game_question_id = ?1 ORDER BY position, id",
   466	        )?;
   467	        state.options = statement
   468	            .query_map([question_id], |row| {
   469	                Ok(GameOptionState {
   470	                    id: row.get(0)?,
   471	                    text: row.get(1)?,
   472	                    answers: None,
   473	                    correct: None,
   474	                })
   475	            })?
   476	            .collect::<rusqlite::Result<Vec<_>>>()?;
   477	    } else if game.status == "closed" {
   478	        let mut statement = connection.prepare(
   479	            "SELECT option.id, option.body, option.is_correct, COUNT(answer.id)
   480	             FROM game_options option
   481	             LEFT JOIN answers answer
   482	               ON answer.option_id = option.id AND answer.game_question_id = option.game_question_id
   483	             WHERE option.game_question_id = ?1
   484	             GROUP BY option.id, option.body, option.is_correct
   485	             ORDER BY option.position, option.id",
   486	        )?;
   487	        state.options = statement
   488	            .query_map([question_id], |row| {
   489	                Ok(GameOptionState {
   490	                    id: row.get(0)?,
   491	                    text: row.get(1)?,
   492	                    correct: Some(row.get::<_, i64>(2)? != 0),
   493	                    answers: Some(row.get(3)?),
   494	                })
   495	            })?
   496	            .collect::<rusqlite::Result<Vec<_>>>()?;
   497	    }
   498	    Ok(Some(state))
   499	}
